137:  function morgueModal(){const actions=[];if(!S.evidence.includes('autopsy'))actions.push({label:'REQUEST PRELIMINARY AUTOPSY',kind:'primary',run:()=>{addEvidence('autopsy');advance(28,'morgue');log('Medical examiner consulted','Dr. Nora Vale estimates death between 19:40 and 20:20. The staged arrangement happened after death.');openModal('Dr. Nora Vale','COUNTY MEDICAL EXAMINER',`<p>Dr. Vale turns a page in the preliminary report. There are no reliable injuries pointing to a ritual. The estimate is broad, but places the death before the scene was arranged.</p><div class="statusline">FORENSIC REPORT · ESTIMATED WINDOW 19:40–20:20</div><p class="subtle">Cause of death is pending full toxicology. A precise time cannot be claimed yet.</p>`,[{label:'THANK THE DOCTOR',run:closeModal}])}});else actions.push({label:'ASK ABOUT TOXICOLOGY',run:()=>{S.flags.toxAsked=true;advance(12);openModal('Pending toxicology','MEDICAL EXAMINER · FOLLOW-UP',`<p>The lab has not found a result that changes the initial assessment. Dr. Vale cautions that the sample is degraded and should not be used to identify a suspect.</p><div class="statusline">NO NEW FORENSIC CONCLUSION</div>`,[{label:'RETURN',run:closeModal}])}});actions.push({label:'LEAVE',run:closeModal});openModal('County Medical Examiner','AUTOPSY WING · RESTRICTED',`<p>The corridor hums with old fluorescent lights. Dr. Nora Vale has agreed to share the preliminary report, but asks that uncertainty be preserved in every copy.</p><div class="statusline">DECEDENT: MARA VENN · REPORT STATUS: ${S.evidence.includes('autopsy')?'PRELIMINARY FILED':'AVAILABLE'}</div>`,actions)}
