*{box-sizing:border-box}
 :root{--ink:#d8d1c2;--muted:#85867f;--faint:#545852;--panel:#171a18;--line:#303531;--gold:#bd9a63;--red:#bd655b;--green:#94a58a}
 html,body{height:100%;margin:0;background:#101211;color:var(--ink);font-family:'DM Sans',sans-serif}
body{overflow:hidden}
.game-shell{height:100%;min-height:580px;max-width:1800px;margin:auto;padding:0 27px 22px;display:flex;flex-direction:column}
.topbar{height:83px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #2b302d;flex-shrink:0}
.brand{display:flex;align-items:center;gap:14px}
.sigil{width:37px;height:37px;border:1px solid #826b49;color:var(--gold);display:grid;place-items:center;font-size:21px;transform:rotate(45deg);margin:0 4px}
.sigil::first-letter{transform:rotate(-45deg)}
.eyebrow{font:10px 'DM Mono',monospace;letter-spacing:1.55px;color:#8d8c81}
.brand h1{font:600 16px 'Playfair Display',serif;letter-spacing:1.2px;margin:4px 0 0}
.brand h1 span{color:#8b7454;font-size:12px;padding:0 3px}
.top-meta{display:flex;align-items:center;gap:25px}
.weather{font:10px 'DM Mono',monospace;color:#9da29b;letter-spacing:1px}
.weather-icon{color:#8393a2;font-size:17px;margin-right:6px}
.day-stamp{display:flex;flex-direction:column;gap:3px;border-left:1px solid var(--line);padding-left:20px;font:10px 'DM Mono',monospace;color:#898c86}
.day-stamp b{font-size:15px;color:#d4cbb8;font-weight:400}
.icon-button,.dots{border:1px solid #383d39;background:transparent;color:#a8a99f;width:34px;height:32px;cursor:pointer}
.icon-button:hover,.dots:hover{border-color:var(--gold);color:var(--gold)}
.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 326px;gap:19px;flex:1;min-height:0;padding-top:18px}
.world-column{min-height:0;display:flex;flex-direction:column}
.scene-wrap{position:relative;overflow:hidden;flex:1;min-height:300px;background:#1a2220;border:1px solid #383b35;box-shadow:0 14px 40px #0005}
.scene-wrap canvas{display:block;width:100%;height:100%;image-rendering:auto}
.scene-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,#0b0f0d9c 0%,transparent 25%,transparent 72%,#0b0e0de0 100%),radial-gradient(ellipse at center,transparent 30%,#0609088c 100%);box-shadow:inset 0 0 0 1px #ffffff08}
.scene-heading{position:absolute;left:22px;top:18px;color:#c0bcad;font:10px 'DM Mono',monospace;letter-spacing:1.4px;display:flex;align-items:center;gap:9px;text-shadow:0 1px #000}
.live-dot{height:6px;width:6px;border-radius:50%;background:#a96e5c;box-shadow:0 0 9px #bd655b}
.scene-coordinates{position:absolute;right:21px;top:18px;color:#9c9e94;font:9px 'DM Mono',monospace;letter-spacing:1px}
.scene-bottom{position:absolute;bottom:0;left:0;right:0;display:flex;justify-content:space-between;align-items:end;padding:22px 23px 18px}
.objective{display:flex;align-items:center;gap:12px}
.objective-mark{color:var(--gold);font-size:19px}
.objective small,.objective strong{display:block}
.objective small{font:9px 'DM Mono',monospace;color:#99968a;letter-spacing:1.4px;margin-bottom:4px}
.objective strong{font:500 14px 'Playfair Display',serif;color:#e3ddcf}
.world-controls{display:flex;gap:14px;font:10px 'DM Mono',monospace;color:#d0cbbc}
.world-controls i{font-style:normal;color:#86877f;font-size:8px;margin-left:4px}
.interact-prompt{position:absolute;left:50%;top:52%;transform:translate(-50%,-50%);background:#111613e8;border:1px solid #9a8055;padding:9px 14px;color:#ddd5c5;font:10px 'DM Mono',monospace;letter-spacing:1px;display:flex;align-items:center;gap:9px;white-space:nowrap;box-shadow:0 3px 20px #0008;pointer-events:none}
.interact-prompt span{border:1px solid #786848;color:var(--gold);padding:3px 6px}
.hidden{display:none!important}
.rain-layer{position:absolute;inset:0;pointer-events:none;opacity:.32;background:repeating-linear-gradient(105deg,transparent 0 39px,#9caeb30e 40px,#bbc8cc15 41px,transparent 42px 75px);animation:rain 1.4s linear infinite}
@keyframes rain{to{background-position:0 70px}
}
.footbar{height:77px;flex-shrink:0;display:flex;align-items:center;justify-content:space-between;border:1px solid #303531;border-top:0;background:#161917;padding:0 15px}
.player-readout{display:flex;align-items:center;gap:10px;min-width:220px}
.portrait{width:34px;height:34px;border:1px solid #646256;background:linear-gradient(145deg,#454942,#222722);display:grid;place-items:center;color:#c9b991;font:600 17px 'Playfair Display',serif}
.player-readout strong,.player-readout small{display:block}
.player-readout strong{font:10px 'DM Mono',monospace;letter-spacing:.5px;color:#c8c3b4}
.player-readout small{font:8px 'DM Mono',monospace;letter-spacing:.8px;color:#777b73;margin-top:5px}
.vitals{display:flex;gap:19px}
.vital{display:grid;grid-template-columns:auto 70px auto;align-items:center;gap:7px}
.vital span{font:8px 'DM Mono',monospace;color:#8d8e85;letter-spacing:.6px}
.vital b{font:9px 'DM Mono',monospace;color:#b8b4a7;font-weight:400}
.meter{height:3px;background:#333833;width:66px}
.meter i{height:100%;display:block;width:94%;background:#93a187}
.meter.sanity i{background:#a28762}
.meter.fatigue i{background:#748894}
.foot-actions{display:flex;gap:8px}
.small-button{background:#202420;border:1px solid #3a4039;color:#b8b5a8;padding:8px 10px;cursor:pointer;font-size:12px}
.small-button:hover{border-color:#90764f}
.small-button span{font:8px 'DM Mono',monospace;letter-spacing:1px;margin-left:3px}
.case-sidebar{background:#171a18;border:1px solid #303531;display:flex;flex-direction:column;min-height:0}
.case-head{padding:21px 19px 14px;display:flex;justify-content:space-between;align-items:center}
.case-head .eyebrow{font-size:9px;letter-spacing:1.1px}
.case-id{color:#88724f;margin-left:5px}
.case-head h2{font:600 21px 'Playfair Display',serif;margin:6px 0 0;color:#e1dbcd}
.dots{border:0;letter-spacing:2px}
.case-summary{padding:0 19px 15px;border-bottom:1px solid var(--line)}
.case-summary p{margin:0 0 17px;color:#a6a69c;font:12px/1.55 'DM Sans',sans-serif;max-width:270px}
.case-stats{display:flex;gap:24px}
.case-stats div{display:flex;align-items:baseline;gap:5px}
.case-stats strong{font:15px 'DM Mono',monospace;color:#d5c7aa;font-weight:400}
.case-stats span{font:8px 'DM Mono',monospace;color:#85877e;letter-spacing:.4px}
.sidebar-section{padding:15px 19px 8px}
.section-title{font:9px 'DM Mono',monospace;letter-spacing:1.2px;color:#9b9b90;margin-bottom:10px;display:flex;align-items:center;gap:8px}
.section-count{color:#77796f;border:1px solid #343934;padding:2px 5px;font-size:8px}
.lead-card{width:100%;display:flex;align-items:center;text-align:left;background:transparent;border:1px solid transparent;color:#cbc7b9;padding:7px 5px;margin:1px 0;gap:10px;cursor:pointer}
.lead-card:hover,.lead-card.active{background:#202420;border-color:#393d36}
.lead-icon{width:25px;height:25px;display:grid;place-items:center;border:1px solid #51463b;color:#bd9161;font-size:13px;flex-shrink:0}
.lead-icon.witness{color:#8c9a8b;border-color:#414c43}
.lead-icon.symbol{color:#9e8f74;border-color:#4b4539}
.lead-card span:nth-child(2){flex:1}
.lead-card b,.lead-card small{display:block}
.lead-card b{font:500 11px 'DM Sans',sans-serif}
.lead-card small{font:9px 'DM Sans',sans-serif;color:#888b82;margin-top:4px}
.lead-arrow{color:#817960;font-size:12px}
.people-section{border-top:1px solid var(--line);margin-top:7px;padding-top:14px}
.person-row{display:flex;align-items:center;width:100%;text-align:left;background:none;border:0;color:#d1ccbe;padding:5px 0;gap:9px;cursor:pointer}
.person-row:hover .person-info b{color:var(--gold)}
.person-avatar{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;font:9px 'DM Mono',monospace;color:#ddd1bb;border:1px solid #756858;background:#37332e}
.avatar-two{background:#2e3633;border-color:#58645a}
.avatar-unknown{color:#aa8c68;background:#292722;border-color:#6d604d}
.person-info{flex:1}
.person-info b,.person-info small{display:block}
.person-info b{font-size:10px;font-weight:500}
.person-info small{font-size:9px;color:#85877f;margin-top:3px}
.suspicion{height:3px;width:28px;background:#383b35}
.suspicion i{height:100%;display:block;width:var(--level);background:#ab7459}
.pressure-section{border-top:1px solid var(--line);margin-top:7px;padding-top:14px}
.pulse-live{color:#80927f;font-size:8px;border:1px solid #414a3f;padding:2px 5px}
.pulse-card{position:relative;padding:11px 11px 10px 31px;background:#1c211d;border:1px solid #333a33}
.pulse-glyph{position:absolute;left:11px;top:11px;color:#ae9469;font-size:14px}
.pulse-card p{font:10px/1.45 'DM Sans',sans-serif;color:#b9b8ac;margin:0 0 9px}
.pulse-card small{font:8px 'DM Mono',monospace;color:#777d74;letter-spacing:.5px}
.sidebar-bottom{margin-top:auto;border-top:1px solid var(--line);padding:12px 18px;display:flex;flex-direction:column;gap:10px}
.sidebar-bottom>span{font:8px 'DM Mono',monospace;color:#716f63;letter-spacing:1.3px}
.sidebar-bottom button{background:#282821;border:1px solid #60543f;padding:10px;color:#dbceb4;text-align:left;font:9px 'DM Mono',monospace;letter-spacing:1px;cursor:pointer}
.sidebar-bottom button:hover{background:#353328}
.sidebar-bottom button b{font-size:8px;border:1px solid #756849;padding:3px 5px;margin-left:8px;color:#c5ab7c}
.sidebar-bottom button span{float:right;color:#9f8961}
.mobile-nav{display:none}
.toast{position:fixed;bottom:25px;left:50%;transform:translate(-50%,20px);background:#1b201c;border:1px solid #85704b;padding:11px 16px;color:#e0d5bd;font:11px 'DM Mono',monospace;letter-spacing:.4px;opacity:0;transition:.25s;z-index:20;pointer-events:none}
.toast.show{opacity:1;transform:translate(-50%,0)}
.scene-photo,.event-visual{margin:0 0 16px;background:#111714;border:1px solid #47483e;padding:7px}
.scene-photo img,.event-visual img{display:block;width:100%;height:auto;aspect-ratio:960/420;object-fit:cover}
.scene-photo figcaption,.event-visual figcaption{padding:7px 4px 2px;color:#b29a70;font:9px 'DM Mono',monospace;letter-spacing:1px}
.event-list article{display:grid;grid-template-columns:minmax(90px,150px) minmax(0,1fr);column-gap:14px;align-items:start}
.event-list article .event-visual{grid-row:1/4;grid-column:1;margin:0}
.event-list article>b,.event-list article>strong,.event-list article>p{grid-column:2}
.event-list article>b{grid-row:1}
.event-list article>strong{grid-row:2}
.event-list article>p{grid-row:3}
.event-list article .event-visual img{aspect-ratio:4/3}
.event-list article .event-visual figcaption{font-size:7px;letter-spacing:.5px}
.scene-photo{margin-bottom:16px}
/* evidence analysis board */
.board-clues{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:9px;margin:15px 0}
.board-clue{min-height:76px;text-align:left;background:#202521;border:1px solid #3c423b;padding:11px;color:#d0c3a6;cursor:pointer}
.board-clue:hover,.board-clue.selected{border-color:#b79865;background:#302d24}
.board-clue b,.board-clue small{display:block}
.board-clue b{font:10px 'DM Mono',monospace}
.board-clue small{margin-top:7px;color:#85877d;font:8px 'DM Mono',monospace}
.board-selection{color:#b29a70;font:9px 'DM Mono',monospace;letter-spacing:1px}
.board-feedback{margin-top:15px;padding:13px;border:1px solid #484b40;background:#202521}
.board-feedback b,.board-feedback span{display:block}
.board-feedback b{color:#d5c6a7}
.board-feedback span{margin-top:5px;color:#b29a70;font:8px 'DM Mono',monospace;letter-spacing:.7px}
.board-feedback p{margin:9px 0 0}
.board-feedback.supported{border-color:#68785e}
.board-feedback.tension{border-color:#8b744d}
/* investigation panels */
.modal-backdrop{position:fixed;inset:0;background:#080b09c9;z-index:30;display:grid;place-items:center;padding:20px;backdrop-filter:blur(4px)}
.modal{background:#171b18;border:1px solid #4a4b40;width:min(760px,100%);max-height:min(700px,92vh);overflow:auto;box-shadow:0 24px 90px #000b}
.modal-top{padding:20px 24px 15px;border-bottom:1px solid #373b35;display:flex;justify-content:space-between;align-items:start}
.modal-top .eyebrow{font-size:9px}
.modal-top h2{font:600 25px 'Playfair Display',serif;margin:6px 0 0;color:#e1dbce}
.close-modal{background:none;border:1px solid #41453e;color:#b4b1a5;width:29px;height:29px;cursor:pointer}
.modal-body{padding:20px 24px 25px;color:#b9baaf;font:13px/1.65 'DM Sans',sans-serif}
.modal-body p{margin:0 0 14px}
.modal-actions{display:flex;flex-wrap:wrap;gap:9px;margin-top:19px}
.action-button{background:#272c27;color:#ddd4c1;border:1px solid #5b584a;padding:10px 13px;font:10px 'DM Mono',monospace;letter-spacing:.5px;cursor:pointer}
.action-button:hover{background:#34382f;border-color:#aa8a5d}
.action-button.primary{background:#605039;border-color:#997d53;color:#f0e2c6}
.action-button.danger{border-color:#85544b;color:#d59c8d}
.dialogue-line{border-left:2px solid #927952;padding:8px 0 8px 14px;margin:13px 0;color:#d1c7b1;font:italic 15px 'Playfair Display',serif}
.evidence-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:15px}
.evidence-item{background:#202521;border:1px solid #3c423b;padding:12px}
.evidence-item b{display:block;font:10px 'DM Mono',monospace;letter-spacing:.5px;color:#d0c3a6}
.evidence-item small{display:block;color:#92958b;font-size:10px;line-height:1.45;margin-top:6px}
.tag{display:inline-block;color:#83917e;border:1px solid #495446;padding:2px 5px;font:8px 'DM Mono',monospace;letter-spacing:.5px;margin-top:8px}
.tag.unverified{color:#ae9271;border-color:#5b4b3b}
.tab-row{display:flex;border-bottom:1px solid #3b4039;margin:0 24px}
.tab-button{background:none;border:0;color:#8f9188;font:9px 'DM Mono',monospace;letter-spacing:1px;padding:12px 14px;cursor:pointer}
.tab-button.selected{color:#d8c8a9;border-bottom:1px solid var(--gold)}
.clue-row{display:flex;align-items:center;gap:12px;border-bottom:1px solid #333833;padding:11px 0}
.clue-row input{accent-color:#a88b5d;width:15px;height:15px}
.clue-row b{display:block;font-size:11px;color:#ddd4c4}
.clue-row small{display:block;color:#858981;font-size:10px}
.note-area{width:100%;min-height:100px;background:#202420;border:1px solid #454a42;color:#ddd5c6;padding:12px;font:12px/1.5 'DM Sans',sans-serif;resize:vertical}
.board{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.board .evidence-item{min-height:82px}
.map-legend{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:12px}
.map-place{background:#202521;border:1px solid #394038;text-align:left;color:#c9c4b8;padding:11px;cursor:pointer;font-size:11px}
.map-place small{display:block;color:#8c9086;margin-top:4px}
.event-log{border-left:1px solid #57533f;margin-left:5px;padding-left:17px}
.event-log article{position:relative;margin:0 0 17px}
.event-log article:before{content:'';position:absolute;left:-21px;top:5px;width:7px;height:7px;background:#a58a5c;border-radius:50%}
.event-log small{display:block;color:#8e8f85;font:9px 'DM Mono',monospace}
.event-log b{display:block;color:#d4c9b4;font-size:12px;margin:3px 0}
.event-log p{font-size:11px;margin:0;color:#9ea096}
.outcome{font:600 27px 'Playfair Display',serif;color:#d6c6a5;margin-bottom:10px}
.subtle{font-size:11px;color:#92958b}
.statusline{font:9px 'DM Mono',monospace;letter-spacing:.6px;color:#9c8b69;margin:10px 0}
.person-details{display:flex;gap:14px;align-items:center;margin-bottom:15px}
.person-details .person-avatar{width:47px;height:47px;font-size:13px}
.person-details h3{margin:0;color:#e0d7c6;font:18px 'Playfair Display',serif}
.person-details small{color:#98998f;font:10px 'DM Mono',monospace}
.audio-pulse{height:14px;width:70px;display:flex;gap:3px;align-items:center}
.audio-pulse i{height:5px;width:2px;background:#a98d61;animation:wave .5s ease-in-out infinite alternate}
.audio-pulse i:nth-child(2n){animation-delay:.2s}
.audio-pulse i:nth-child(3n){animation-delay:.35s}
@keyframes wave{to{height:13px}
}
@media(max-width:1050px){.game-shell{padding:0 15px 15px}
.game-layout{grid-template-columns:minmax(0,1fr) 290px;gap:12px}
.case-head{padding:16px 14px 12px}
.case-summary,.sidebar-section{padding-left:14px;padding-right:14px}
.sidebar-bottom{padding:11px 14px}
.vitals{gap:10px}
.vital{grid-template-columns:auto 46px auto;gap:5px}
.meter{width:45px}
.player-readout{min-width:170px}
.world-controls{gap:8px}
.world-controls span{font-size:9px}
}
.mobile-controls{display:none}
.scene-wrap{isolation:isolate}
.scene-wrap canvas{position:absolute;inset:0}
.scene-wrap #townMap{display:none;z-index:1;cursor:crosshair;touch-action:manipulation;background:#28332e}
.scene-wrap.map-open #world{display:none}
.scene-wrap.map-open #townMap{display:block}
.scene-wrap.map-open .scene-vignette{background:linear-gradient(180deg,#0b0f0d7d 0%,transparent 18%,transparent 82%,#0b0e0d99 100%),radial-gradient(ellipse at center,transparent 48%,#0609085c 100%)}
.map-toggle{position:absolute;z-index:8;right:18px;top:48px;display:flex;align-items:center;gap:7px;background:#141916e8;border:1px solid #82734f;color:#d7c39d;padding:8px 11px;font:10px 'DM Mono',monospace;letter-spacing:1px;cursor:pointer}
.map-toggle:hover,.map-toggle[aria-pressed="true"]{background:#5b4b32;color:#fff0d3}
.map-toggle:focus-visible,.mobile-nav button:focus-visible,.touch-dir:focus-visible,.touch-action:focus-visible{outline:2px solid #d0ad70;outline-offset:2px}
.fps-compass{position:absolute;z-index:3;top:16px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:8px;padding:7px 10px;background:#111713b8;border:1px solid #ffffff24;color:#cfc4aa;font:10px 'DM Mono',monospace;letter-spacing:1px}
.fps-compass i{width:24px;height:1px;background:#b8a47f;position:relative}
.fps-compass i:after{content:'';position:absolute;left:11px;top:-3px;border:3px solid transparent;border-bottom-color:#b8a47f}
.fps-compass b{font-weight:500;color:#e3c991}
.fps-reticle{position:absolute;z-index:3;top:49%;left:50%;width:17px;height:17px;transform:translate(-50%,-50%);opacity:.72}
.fps-reticle:before,.fps-reticle:after{content:'';position:absolute;background:#e4d7ba;box-shadow:0 0 3px #000}
.fps-reticle:before{width:1px;height:17px;left:8px}
.fps-reticle:after{height:1px;width:17px;top:8px}
.route-indicator{position:absolute;z-index:4;top:60px;left:50%;transform:translate(-50%,-5px);opacity:0;pointer-events:none;background:#171c19dd;border:1px solid #88724d;color:#ddc99f;padding:6px 9px;font:9px 'DM Mono',monospace;letter-spacing:.7px;transition:.18s}
.route-indicator.visible{opacity:1;transform:translate(-50%,0)}
.scene-wrap.map-open .fps-reticle,.scene-wrap.map-open .scene-bottom,.scene-wrap.map-open .interact-prompt,.scene-wrap.map-open .mobile-controls{display:none}
.scene-wrap.map-open .scene-heading{z-index:3;background:#111713bb;padding:7px 9px}
.scene-wrap.map-open .scene-coordinates{z-index:3;background:#111713bb;padding:7px 9px}
.scene-wrap.map-open .map-toggle{z-index:5}
@media(max-width:760px){body{overflow:auto}
.game-shell{height:100dvh;min-height:630px;padding:0 10px 8px}
.topbar{height:67px}
.brand{gap:9px}
.sigil{height:30px;width:30px;font-size:17px}
.brand .eyebrow{font-size:8px;letter-spacing:.8px}
.brand h1{font-size:12px;letter-spacing:.4px}
.top-meta{gap:9px}
.weather{display:none}
.day-stamp{padding-left:9px}
.icon-button{width:29px;height:29px}
.game-layout{display:block;padding-top:9px;min-height:0}
.world-column{height:calc(100% - 1px)}
.scene-wrap{min-height:330px;touch-action:manipulation}
.scene-wrap canvas{touch-action:none}
.mobile-controls{display:flex;position:absolute;z-index:5;left:12px;right:12px;bottom:84px;align-items:flex-end;justify-content:space-between;pointer-events:none}
.touch-pad{width:132px;height:132px;position:relative;pointer-events:auto;touch-action:none}
.touch-dir,.touch-action{background:#171c19df;border:1px solid #80765f;color:#e3d4b8;box-shadow:0 3px 12px #0008;touch-action:none;-webkit-tap-highlight-color:transparent}
.touch-dir{position:absolute;width:43px;height:43px;border-radius:12px;font-size:17px}
.touch-dir:active,.touch-dir.pressed,.touch-action:active{background:#66563c;border-color:#c3a36b}
.touch-up{top:0;left:44px}
.touch-left{top:44px;left:0}
.touch-down{top:44px;left:44px}
.touch-right{top:44px;right:0}
.touch-center{position:absolute;bottom:0;left:45px;color:#a49a85;font:8px 'DM Mono',monospace;letter-spacing:1px}
.touch-actions{display:flex;flex-direction:column;gap:8px;align-items:flex-end;pointer-events:auto}
.touch-action{min-width:94px;min-height:44px;padding:0 12px;border-radius:22px;font:9px 'DM Mono',monospace;letter-spacing:.7px}
.footbar{height:66px;padding:0 9px}
.player-readout{min-width:0}
.player-readout strong{font-size:8px}
.player-readout small{font-size:7px}
.portrait{width:29px;height:29px}
.vitals{gap:7px}
.vital{display:flex;flex-direction:column;gap:3px;align-items:flex-start}
.vital span{font-size:7px}
.vital b{display:none}
.meter{width:40px;height:3px}
.foot-actions{display:none}
.world-controls{gap:7px}
.world-controls span{font-size:8px}
.world-controls i{font-size:7px}
.scene-bottom{padding:14px 12px}
.objective strong{font-size:12px}
.objective small{font-size:8px}
.scene-heading{left:12px;top:13px;font-size:8px}
.scene-coordinates{right:12px;top:13px;font-size:8px}
.case-sidebar{display:none}
.mobile-nav{position:absolute;display:flex;left:10px;right:10px;bottom:8px;justify-content:center;gap:7px;pointer-events:none}
.mobile-nav button{pointer-events:auto;background:#202420e8;border:1px solid #555344;color:#cfc5b0;padding:8px 13px;font:9px 'DM Mono',monospace;letter-spacing:1px}
.game-shell{padding-bottom:43px}
.modal{max-height:88vh}
.modal-top{padding:16px 17px 12px}
.modal-body{padding:15px 17px 20px}
.modal-top h2{font-size:22px}
.tab-row{margin:0 17px}
.tab-button{padding:10px 9px;font-size:8px}
.evidence-list{grid-template-columns:1fr}
.board{grid-template-columns:1fr 1fr}
.mobile-nav{bottom:8px}
